    static readonly Brush Ink=new SolidColorBrush(Color.FromRgb(29,35,48)),Muted=new SolidColorBrush(Color.FromRgb(108,116,134)),Accent=new SolidColorBrush(Color.FromRgb(94,92,230)),Surface=new SolidColorBrush(Color.FromRgb(246,247,251));
    public ControlCenter(PetWindow owner) {
        pet=owner;Title="Grok · 控制中心";Width=1040;Height=760;MinWidth=900;MinHeight=650;
        WindowStartupLocation=WindowStartupLocation.CenterScreen;Background=Surface;FontFamily=new("Microsoft YaHei UI");FontSize=13;Foreground=Ink;
        profiles=Program.Config.Clone().Connections;selectedProfileId=activeId=Program.Config.ActiveConnectionId;
        StyleControls();
        var root=new Grid{Background=Surface};root.ColumnDefinitions.Add(new(){Width=new GridLength(205)});root.ColumnDefinitions.Add(new());root.RowDefinitions.Add(new(){Height=new GridLength(94)});root.RowDefinitions.Add(new());root.RowDefinitions.Add(new(){Height=new GridLength(70)});
        var side=new Grid{Background=new SolidColorBrush(Color.FromRgb(21,24,33))};side.RowDefinitions.Add(new(){Height=new GridLength(126)});side.RowDefinitions.Add(new());side.RowDefinitions.Add(new(){Height=new GridLength(116)});Grid.SetRowSpan(side,3);root.Children.Add(side);
        var brand=new StackPanel{Margin=new(22,25,20,0)};var brandRow=new StackPanel{Orientation=Orientation.Horizontal};brandRow.Children.Add(new FacePreview{Width=38,Height=38});brandRow.Children.Add(new TextBlock{Text="GROK",Foreground=Brushes.White,FontSize=23,FontWeight=FontWeights.Bold,VerticalAlignment=VerticalAlignment.Center,Margin=new(10,0,0,0)});brand.Children.Add(brandRow);side.Children.Add(brand);
        var menu=new StackPanel{Margin=new(12,0,12,0)};Grid.SetRow(menu,1);side.Children.Add(menu);
