            var b=new Button{Content=name,HorizontalContentAlignment=HorizontalAlignment.Left,Padding=new(17,13,12,13),Margin=new(0,3,0,3),Foreground=new SolidColorBrush(Color.FromRgb(172,180,200)),Background=Brushes.Transparent,BorderThickness=new(0)};b.Click+=(_,_)=>SelectPage(name);menu.Children.Add(b);nav[name]=b;
        }
        var sideBottom=new StackPanel{Margin=new(24,15,20,15)};sideBottom.Children.Add(new TextBlock{Text="●  COMPANION STATUS",FontSize=9,Foreground=new SolidColorBrush(Color.FromRgb(137,146,169)),Margin=new(0,0,0,10)});sideBottom.Children.Add(status);sideBottom.Children.Add(new TextBlock{Text="v0.2 · Windows",FontSize=10,Foreground=new SolidColorBrush(Color.FromRgb(108,116,138)),Margin=new(0,13,0,0)});Grid.SetRow(sideBottom,2);
        var header=new Grid{Margin=new(30,20,30,14)};header.ColumnDefinitions.Add(new());header.ColumnDefinitions.Add(new(){Width=GridLength.Auto});var heading=new StackPanel();heading.Children.Add(title);header.Children.Add(heading);
        var topButton=Button("回到桌宠",()=>{if(!pet.IsVisible)pet.Show();pet.ResetPosition();});Grid.SetColumn(topButton,1);header.Children.Add(topButton);Grid.SetColumn(header,1);root.Children.Add(header);
        var scroll=new ScrollViewer{Content=content,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled,Padding=new(30,0,30,22)};Grid.SetColumn(scroll,1);Grid.SetRow(scroll,1);root.Children.Add(scroll);
        var footer=new Grid{Margin=new(30,12,30,18)};footer.ColumnDefinitions.Add(new());footer.ColumnDefinitions.Add(new(){Width=GridLength.Auto});footer.Children.Add(notice);var save=Button("保存设置",SaveAll,true);Grid.SetColumn(save,1);footer.Children.Add(save);Grid.SetColumn(footer,1);Grid.SetRow(footer,2);root.Children.Add(footer);Content=root;
        pet.ReplyReceived+=OnReply;statusTimer.Tick+=(_,_)=>UpdateStatus();statusTimer.Start();Closed+=(_,_)=>{statusTimer.Stop();pet.ReplyReceived-=OnReply;};
