    void StyleControls(){
        var buttons=new Style(typeof(Button));buttons.Setters.Add(new Setter(Control.CursorProperty,Cursors.Hand));buttons.Setters.Add(new Setter(Control.PaddingProperty,new Thickness(16,9,16,9)));buttons.Setters.Add(new Setter(Control.BackgroundProperty,Brushes.White));buttons.Setters.Add(new Setter(Control.ForegroundProperty,Ink));buttons.Setters.Add(new Setter(Control.BorderBrushProperty,new SolidColorBrush(Color.FromRgb(225,229,239))));buttons.Setters.Add(new Setter(Control.BorderThicknessProperty,new Thickness(1)));
        var template=new ControlTemplate(typeof(Button));var border=new FrameworkElementFactory(typeof(Border));border.SetValue(Border.CornerRadiusProperty,new CornerRadius(9));border.SetValue(Border.BackgroundProperty,new TemplateBindingExtension(Control.BackgroundProperty));border.SetValue(Border.BorderBrushProperty,new TemplateBindingExtension(Control.BorderBrushProperty));border.SetValue(Border.BorderThicknessProperty,new TemplateBindingExtension(Control.BorderThicknessProperty));border.SetValue(Border.PaddingProperty,new TemplateBindingExtension(Control.PaddingProperty));var cp=new FrameworkElementFactory(typeof(ContentPresenter));cp.SetValue(ContentPresenter.HorizontalAlignmentProperty,new TemplateBindingExtension(Control.HorizontalContentAlignmentProperty));cp.SetValue(ContentPresenter.VerticalAlignmentProperty,VerticalAlignment.Center);border.AppendChild(cp);template.VisualTree=border;buttons.Setters.Add(new Setter(Control.TemplateProperty,template));var hover=new Trigger{Property=IsMouseOverProperty,Value=true};hover.Setters.Add(new Setter(OpacityProperty,.78));buttons.Triggers.Add(hover);var disabled=new Trigger{Property=IsEnabledProperty,Value=false};disabled.Setters.Add(new Setter(OpacityProperty,.45));buttons.Triggers.Add(disabled);Resources.Add(typeof(Button),buttons);
        foreach(var type in new[]{typeof(TextBox),typeof(PasswordBox),typeof(ComboBox)}){var style=new Style(type);style.Setters.Add(new Setter(Control.PaddingProperty,new Thickness(10,8,10,8)));style.Setters.Add(new Setter(Control.BorderBrushProperty,new SolidColorBrush(Color.FromRgb(215,221,235))));style.Setters.Add(new Setter(Control.BackgroundProperty,Brushes.White));style.Setters.Add(new Setter(Control.ForegroundProperty,Ink));Resources.Add(type,style);}
        var checks=new Style(typeof(CheckBox));checks.Setters.Add(new Setter(MarginProperty,new Thickness(0,7,0,7)));checks.Setters.Add(new Setter(Control.ForegroundProperty,Ink));Resources.Add(typeof(CheckBox),checks);
    }
    static TextBlock Text(string text,double size=13,Brush? brush=null)=>new(){Text=text,FontSize=size,Foreground=brush??Ink,TextWrapping=TextWrapping.Wrap};
    Button Button(string text,Action action,bool primary=false){var b=new Button{Content=text,HorizontalContentAlignment=HorizontalAlignment.Center,Margin=new(0,0,8,0)};if(primary){b.Background=Accent;b.Foreground=Brushes.White;b.BorderThickness=new(0);}b.Click+=(_,_)=>action();return b;}
    StackPanel Page()=>new(){Margin=new(0,4,0,0)};
    Border Card(string heading,string description,UIElement body){var stack=new StackPanel();stack.Children.Add(new TextBlock{Text=heading,FontSize=16,FontWeight=FontWeights.SemiBold,Margin=new(0,0,0,6)});stack.Children.Add(body);return new Border{Background=Brushes.White,BorderBrush=new SolidColorBrush(Color.FromRgb(230,233,241)),BorderThickness=new(1),CornerRadius=new(15),Padding=new(22),Margin=new(0,0,0,16),Child=stack};}
    void Field(StackPanel parent,string label,UIElement element,string hint=""){parent.Children.Add(new TextBlock{Text=label,FontWeight=FontWeights.Medium,Margin=new(0,10,0,7)});parent.Children.Add(element);}
    public void SelectPage(string name){if(!nav.ContainsKey(name))name="概览";currentPage=name;title.Text=name;subtitle.Text=name switch{"概览"=>"一个会看你、会回应你的桌面伙伴。","模型连接"=>"连接自己的本地模型，或使用兼容格式的 API。","外观与动作"=>"位置跟手，表情贴合球面，动画按你的喜好。","性格与对话"=>"给它名字、性格，再聊上一句。","诊断与数据"=>"连接状态、配置备份与本地数据。",_=>"关于这个桌面伙伴。"};foreach(var (key,b) in nav){b.Background=key==name?new SolidColorBrush(Color.FromRgb(57,57,92)):Brushes.Transparent;b.Foreground=key==name?Brushes.White:new SolidColorBrush(Color.FromRgb(172,180,200));}if(!pages.TryGetValue(name,out var page)){page=name switch{"概览"=>Overview(),"模型连接"=>Connections(),"外观与动作"=>Appearance(),"性格与对话"=>Personality(),"诊断与数据"=>Diagnostics(),_=>About()};pages[name]=page;}content.Content=page;}
    FrameworkElement Overview(){var page=Page();var hero=new Grid();hero.ColumnDefinitions.Add(new(){Width=new GridLength(170)});hero.ColumnDefinitions.Add(new());hero.Children.Add(new FacePreview{Width=150,Height=150});var intro=new StackPanel{VerticalAlignment=VerticalAlignment.Center,Margin=new(15,0,0,0)};intro.Children.Add(new TextBlock{Text=Program.Config.PetName,FontSize=25,FontWeight=FontWeights.SemiBold});var actions=new WrapPanel();actions.Children.Add(Button("轻点互动",()=>_=pet.Interact("用户从控制中心轻轻点了你一下。"),true));actions.Children.Add(Button("预览动作",pet.Preview));intro.Children.Add(actions);Grid.SetColumn(intro,1);hero.Children.Add(intro);page.Children.Add(Card("桌面伙伴","",hero));
        var rows=new StackPanel();rows.Children.Add(Text(Program.Config.Active.Name,15));var shortcuts=new WrapPanel();shortcuts.Children.Add(Button("配置模型",()=>SelectPage("模型连接")));shortcuts.Children.Add(Button("打开本地聊天",pet.OpenLocalChat));shortcuts.Children.Add(Button("调整外观",()=>SelectPage("外观与动作")));rows.Children.Add(shortcuts);page.Children.Add(Card("当前连接","待机不向 AI 发送请求。连续操作只保留最近一条等待中的互动。",rows));
        return page;}
    FrameworkElement Connections(){var page=Page();var profileBar=new Grid();profileBar.ColumnDefinitions.Add(new());profileBar.ColumnDefinitions.Add(new(){Width=GridLength.Auto});profileSelector=new ComboBox{ItemsSource=profiles,SelectedItem=profiles.First(p=>p.Id==selectedProfileId),Margin=new(0,0,10,0)};profileBar.Children.Add(profileSelector);var add=Button("＋ 添加连接",()=>{SaveProfileForm();var p=new ConnectionProfile{Name="新连接 "+(profiles.Count+1),Provider="自定义兼容 API",NativeR1=false,Endpoint="http://127.0.0.1:1234/v1"};profiles.Add(p);selectedProfileId=p.Id;profileSelector.Items.Refresh();switching=true;profileSelector.SelectedItem=p;switching=false;BuildConnectionForm();});Grid.SetColumn(add,1);profileBar.Children.Add(add);page.Children.Add(Card("连接配置","可以保存多套本地或云端连接，选中并启用后点击底部保存。",profileBar));page.Children.Add(Card("服务与模型","API Key 由 Windows 凭据管理器保存，导出配置不会包含密钥。",connectionForm));
        profileSelector.SelectionChanged+=(_,_)=>{if(switching)return;SaveProfileForm();if(profileSelector.SelectedItem is ConnectionProfile p){selectedProfileId=p.Id;BuildConnectionForm();}};
        collect.Add(s=>{SaveProfileForm();s.Connections=profiles.Select(p=>JsonSerializer.Deserialize<ConnectionProfile>(JsonSerializer.Serialize(p))!).ToList();s.ActiveConnectionId=activeId;});BuildConnectionForm();return page;}
    void SaveProfileForm(){if(connectionName==null||endpointBox==null||modelBox==null||keyBox==null)return;var p=profiles.FirstOrDefault(p=>p.Id==selectedProfileId);if(p==null)return;p.Name=string.IsNullOrWhiteSpace(connectionName.Text)?"未命名连接":connectionName.Text.Trim();p.Endpoint=endpointBox.Text.Trim().TrimEnd('/');p.Model=modelBox.Text.Trim();p.Provider=providerSelector?.SelectedItem?.ToString()??"自定义兼容 API";p.NativeR1=nativeCheck?.IsChecked==true;p.JsonMode=jsonCheck?.IsChecked==true;secrets[p.Id]=keyBox.Password;}
    void BuildConnectionForm(){connectionForm.Children.Clear();var p=profiles.First(x=>x.Id==selectedProfileId);connectionName=new TextBox{Text=p.Name};Field(connectionForm,"连接名称",connectionName);providerSelector=new ComboBox{ItemsSource=new[]{"llama.cpp · R1 快速模式","llama.cpp · 兼容 API","LM Studio","Ollama · 兼容 API","DeepSeek API","自定义兼容 API"},SelectedItem=p.Provider};if(providerSelector.SelectedIndex<0)providerSelector.SelectedIndex=5;Field(connectionForm,"服务预设",providerSelector);
        endpointBox=new TextBox{Text=p.Endpoint};Field(connectionForm,"服务地址",endpointBox,"兼容 API 地址通常包含 /v1；本地 R1 快速模式填服务根地址。");
        keyBox=new PasswordBox{Password=secrets.TryGetValue(p.Id,out var secret)?secret:CredentialVault.Get(p.Id)};Field(connectionForm,"API Key",keyBox);
        modelBox=new ComboBox{IsEditable=true,Text=p.Model,MinHeight=36};Field(connectionForm,"模型 ID",modelBox,"可以刷新列表，也可以直接输入服务商提供的模型名称。");
        nativeCheck=new CheckBox{Content="使用 llama.cpp 的 DeepSeek R1 快速端点",IsChecked=p.NativeR1};jsonCheck=new CheckBox{Content="JSON 模式",IsChecked=p.JsonMode};modelBox.IsEnabled=!p.NativeR1;nativeCheck.Checked+=(_,_)=>modelBox.IsEnabled=false;nativeCheck.Unchecked+=(_,_)=>modelBox.IsEnabled=true;connectionForm.Children.Add(nativeCheck);connectionForm.Children.Add(jsonCheck);
        var active=new CheckBox{Content="将这套配置设为当前连接",IsChecked=activeId==p.Id};active.Checked+=(_,_)=>activeId=p.Id;active.Unchecked+=(_,_)=>{if(activeId==p.Id)active.IsChecked=true;};connectionForm.Children.Add(active);
        var result=new TextBlock{Foreground=Muted,TextWrapping=TextWrapping.Wrap,Margin=new(0,10,0,6)};var buttons=new WrapPanel();var fetch=Button("测试连接 / 刷新模型",()=>{});fetch.Click+=async(_,_)=>{fetch.IsEnabled=false;result.Text="正在连接…";try{SaveProfileForm();var models=await ConnectionTools.Models(p,keyBox.Password);modelBox.ItemsSource=models;if(string.IsNullOrWhiteSpace(modelBox.Text)&&models.Count>0)modelBox.Text=models[0];result.Text=$"连接成功 · {models.Count} 个模型";result.Foreground=new SolidColorBrush(Color.FromRgb(28,139,111));}catch(Exception ex){result.Text=ex.Message;result.Foreground=Brushes.IndianRed;}finally{fetch.IsEnabled=true;}};buttons.Children.Add(fetch);
        buttons.Children.Add(Button("删除此连接",()=>{if(profiles.Count==1){Toast("至少保留一套连接。",true);return;}if(MessageBox.Show(this,"删除此连接？","删除连接",MessageBoxButton.YesNo,MessageBoxImage.Question)!=MessageBoxResult.Yes)return;secrets.Remove(p.Id);profiles.Remove(p);selectedProfileId=profiles[0].Id;if(activeId==p.Id)activeId=selectedProfileId;switching=true;profileSelector!.Items.Refresh();profileSelector.SelectedItem=profiles[0];switching=false;BuildConnectionForm();}));connectionForm.Children.Add(buttons);connectionForm.Children.Add(result);
        providerSelector.SelectionChanged+=(_,_)=>{string provider=providerSelector.SelectedItem?.ToString()??"";nativeCheck.IsChecked=provider=="llama.cpp · R1 快速模式";endpointBox.Text=provider switch{"llama.cpp · R1 快速模式"=>"http://127.0.0.1:8080","llama.cpp · 兼容 API"=>"http://127.0.0.1:8080/v1","LM Studio"=>"http://127.0.0.1:1234/v1","Ollama · 兼容 API"=>"http://127.0.0.1:11434/v1","DeepSeek API"=>"https://api.deepseek.com/v1",_=>endpointBox.Text};if(provider=="DeepSeek API")modelBox.Text="deepseek-flash";};}
    FrameworkElement Appearance(){var page=Page();var controls=new StackPanel();Slider AddSlider(string name,double value,double min,double max,Action<Settings,double> setter,string suffix=""){var row=new Grid();row.ColumnDefinitions.Add(new());row.ColumnDefinitions.Add(new(){Width=GridLength.Auto});var label=Text(name);row.Children.Add(label);var number=Text(value.ToString("0.##")+suffix,12,Muted);Grid.SetColumn(number,1);row.Children.Add(number);controls.Children.Add(row);var slider=new Slider{Minimum=min,Maximum=max,Value=value,TickFrequency=(max-min)/20,Margin=new(0,10,0,20)};slider.ValueChanged+=(_,_)=>number.Text=slider.Value.ToString("0.##")+suffix;controls.Children.Add(slider);collect.Add(s=>setter(s,slider.Value));return slider;}
        AddSlider("球体尺寸",Program.Config.Size,96,216,(s,v)=>s.Size=v," px");AddSlider("透明度",Program.Config.Opacity,.35,1,(s,v)=>s.Opacity=v);AddSlider("眼神活动范围",Program.Config.GazeRange,.2,1.1,(s,v)=>s.GazeRange=v);AddSlider("AI 身体动作幅度",Program.Config.Motion,0,1.5,(s,v)=>s.Motion=v);AddSlider("拖拽形变与回弹",Program.Config.Elasticity,0,1.5,(s,v)=>s.Elasticity=v);AddSlider("气泡停留时间",Program.Config.BubbleSeconds,3,20,(s,v)=>s.BubbleSeconds=v," 秒");AddSlider("气泡字号",Program.Config.BubbleFontSize,12,20,(s,v)=>s.BubbleFontSize=v);
        page.Children.Add(Card("外观与动作","拖动位置始终直接跟手。弹性只改变形变和松手回弹，不增加鼠标延迟。",controls));var toggles=new StackPanel();Check(toggles,"保持桌宠在其他窗口上方",Program.Config.AlwaysOnTop,(s,v)=>s.AlwaysOnTop=v);Check(toggles,"眼睛跟随鼠标",Program.Config.EyeTracking,(s,v)=>s.EyeTracking=v);Check(toggles,"减少身体动画（保留眼神）",Program.Config.ReducedMotion,(s,v)=>s.ReducedMotion=v);Check(toggles,"启动时显示控制中心",Program.Config.ShowPanelOnStart,(s,v)=>s.ShowPanelOnStart=v);var actions=new WrapPanel{Margin=new(0,12,0,0)};actions.Children.Add(Button("预览动作",pet.Preview));actions.Children.Add(Button("重置桌宠位置",pet.ResetPosition));actions.Children.Add(Button("显示 / 隐藏桌宠",()=>{if(pet.IsVisible)pet.Hide();else pet.Show();}));toggles.Children.Add(actions);page.Children.Add(Card("桌面行为","关闭控制中心不等于退出桌宠。隐藏后仍可用启动脚本打开控制中心。",toggles));return page;}
    void Check(StackPanel panel,string label,bool value,Action<Settings,bool> setter){var b=new CheckBox{Content=label,IsChecked=value};panel.Children.Add(b);collect.Add(s=>setter(s,b.IsChecked==true));}
    FrameworkElement Personality(){var page=Page();var form=new StackPanel();var name=new TextBox{Text=Program.Config.PetName,MaxLength=24};Field(form,"名字",name);var language=new ComboBox{ItemsSource=new[]{"中文","English","日本語"},SelectedItem=Program.Config.Language};Field(form,"回应语言",language);var personality=new TextBox{Text=Program.Config.Personality,AcceptsReturn=true,TextWrapping=TextWrapping.Wrap,Height=70,MaxLength=500};Field(form,"性格",personality);var extra=new TextBox{Text=Program.Config.ExtraPrompt,AcceptsReturn=true,TextWrapping=TextWrapping.Wrap,Height=70,MaxLength=1200};Field(form,"补充设定",extra,"适合添加称呼、说话风格和角色背景。动作输出格式由程序维护。");var memory=new ComboBox{ItemsSource=new[]{0,2,4,6,8},SelectedItem=Program.Config.MemoryTurns};Field(form,"记忆轮数",memory,"只在内存中保留，不读取网页聊天历史。");var temp=new Slider{Minimum=0,Maximum=1.5,Value=Program.Config.Temperature};Field(form,"回应随机性",temp,"0 更稳定，较高的值更多变化；默认 0.75。");var tokens=new TextBox{Text=Program.Config.MaxTokens.ToString()};Field(form,"单次最大输出 tokens",tokens,"128–2048，默认 480；过低可能截断动作 JSON。");var timeout=new TextBox{Text=Program.Config.TimeoutSeconds.ToString()};Field(form,"请求超时（秒）",timeout,"5–120；网页长篇生成时，桌宠可能排队。");Check(form,"点击时让 AI 回应",Program.Config.ReactToClick,(s,v)=>s.ReactToClick=v);Check(form,"拖拽结束后让 AI 回应",Program.Config.ReactToDrag,(s,v)=>s.ReactToDrag=v);
        collect.Add(s=>{if(!int.TryParse(tokens.Text,out var t)||t<128||t>2048)throw new InvalidDataException("输出 tokens 请填写 128–2048 的整数。");if(!int.TryParse(timeout.Text,out var sec)||sec<5||sec>120)throw new InvalidDataException("超时请填写 5–120 秒。");s.PetName=name.Text;s.Language=language.SelectedItem?.ToString()??"中文";s.Personality=personality.Text;s.ExtraPrompt=extra.Text;s.MemoryTurns=(int)(memory.SelectedItem??4);s.Temperature=temp.Value;s.MaxTokens=t;s.TimeoutSeconds=sec;});page.Children.Add(Card("角色设定","它的台词、眼神与动作关键帧由当前模型理解后生成。",form));
        var chat=new StackPanel();var historyScroll=new ScrollViewer{Content=chatHistory,MaxHeight=260,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};chat.Children.Add(historyScroll);var input=new TextBox{AcceptsReturn=true,Height=70,TextWrapping=TextWrapping.Wrap,MaxLength=500};chat.Children.Add(input);var send=Button("发送给桌宠",()=>{if(string.IsNullOrWhiteSpace(input.Text))return;string text=input.Text.Trim();input.Clear();AddChat("你",text);_=pet.Interact("用户对你说："+text);},true);input.KeyDown+=(_,e)=>{if(e.Key==Key.Enter&&Keyboard.Modifiers==ModifierKeys.Control){send.RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Button.ClickEvent));e.Handled=true;}};var row=new WrapPanel{Margin=new(0,12,0,10)};row.Children.Add(send);row.Children.Add(Button("清空互动记忆",()=>{pet.Service.ClearMemory();chatHistory.Children.Clear();Toast("已清空");}));chat.Children.Add(row);chat.Children.Add(chatHint);page.Children.Add(Card("和它聊聊","Ctrl+Enter 发送。回复会同时出现在桌宠气泡。",chat));return page;}
    FrameworkElement Diagnostics(){var page=Page();var box=new StackPanel();var result=new TextBlock{Text="未检测",Foreground=Muted,TextWrapping=TextWrapping.Wrap,LineHeight=23};box.Children.Add(result);var buttons=new WrapPanel{Margin=new(0,14,0,0)};var test=Button("检查当前连接",()=>{});test.Click+=async(_,_)=>{test.IsEnabled=false;result.Text="正在检查…";try{var p=Program.Config.Active;var models=await ConnectionTools.Models(p,CredentialVault.Get(p.Id));result.Text=$"连接正常\n连接：{p.Name}\n模式：{(p.NativeR1?"本地 R1 快速端点":"兼容 API")}\n可用模型：{string.Join("、",models.Take(3))}\n本次桌宠 AI 请求：{pet.Service.RequestCount} 次\n最近响应：{pet.LastReplySeconds:F2} 秒";}catch(Exception ex){result.Text=ex.Message;}finally{test.IsEnabled=true;}};buttons.Children.Add(test);buttons.Children.Add(Button("打开数据目录",()=>Process.Start(new ProcessStartInfo("explorer.exe",Program.DataDir){UseShellExecute=true})));box.Children.Add(buttons);page.Children.Add(Card("连接与运行状态","一个模型服务可供网页与桌宠共用；请求繁忙时会排队。",box));var data=new StackPanel();var actions=new WrapPanel{Margin=new(0,16,0,0)};actions.Children.Add(Button("导出配置",Export));actions.Children.Add(Button("导入配置",Import));actions.Children.Add(Button("导出诊断摘要",ExportDiagnostics));data.Children.Add(actions);page.Children.Add(Card("备份与迁移","导入前会备份当前配置。API Key 不随配置导入或导出，需要在新电脑重新填写。",data));var startup=new StackPanel();Check(startup,"自动启动本地服务",Program.Config.AutoStartLocalServer,(s,v)=>s.AutoStartLocalServer=v);Check(startup,"启动时打开聊天网页",Program.Config.OpenChatOnLaunch,(s,v)=>s.OpenChatOnLaunch=v);var exe=new TextBox{Text=Program.Config.ServerExecutable};var model=new TextBox{Text=Program.Config.ModelFile};Field(startup,"推理程序",exe,"留空时使用当前电脑已配置的服务路径。");startup.Children.Add(Button("选择推理程序…",()=>{var file=new OpenFileDialog{Filter="llama-server.exe|llama-server.exe|可执行文件|*.exe"};if(file.ShowDialog(this)==true)exe.Text=file.FileName;}));Field(startup,"模型文件",model);startup.Children.Add(Button("选择模型文件…",()=>{var file=new OpenFileDialog{Filter="GGUF 模型|*.gguf"};if(file.ShowDialog(this)==true)model.Text=file.FileName;}));collect.Add(s=>{s.ServerExecutable=exe.Text.Trim();s.ModelFile=model.Text.Trim();});page.Children.Add(Card("启动与本地服务","只有选择本机 8080 端口的 R1 快速模式时，启动脚本才会自动加载模型。API 连接不会启动本地模型。",startup));var quit=new WrapPanel();quit.Children.Add(Button("隐藏控制中心",Hide));quit.Children.Add(Button("退出桌宠",pet.Close));page.Children.Add(Card("结束本次陪伴","退出桌宠保留模型服务。程序没有自动开机启动，也不会后台请求云 API。",quit));return page;}
    FrameworkElement About(){var page=Page();var body=new StackPanel();body.Children.Add(Text("Grok Desktop Companion",24));body.Children.Add(new TextBlock{Text="v0.2",Foreground=Muted,Margin=new(0,12,0,0)});page.Children.Add(Card("关于","",body));return page;}
    void SaveAll(){try{var draft=Program.Config.Clone();foreach(var action in collect)action(draft);draft.Normalize();foreach(var (id,secret) in secrets)CredentialVault.Set(id,secret);foreach(var removed in Program.Config.Connections.Where(old=>!draft.Connections.Any(next=>next.Id==old.Id)))CredentialVault.Set(removed.Id,"");pet.ApplySettings(draft);pages.Remove("概览");Toast("已保存");UpdateStatus();}catch(Exception e){Toast(e.Message,true);}}
    void Toast(string text,bool error=false){notice.Text=text;notice.Foreground=error?Brushes.IndianRed:new SolidColorBrush(Color.FromRgb(28,139,111));}
    void UpdateStatus(){status.Text=pet.IsThinking?"正在理解你的互动…":pet.LastError.Length>0?"连接需要检查":"待机 · 眼神跟随";if(currentPage=="性格与对话")chatHint.Text=pet.IsThinking?"正在等待模型回应…":"";}
    void AddChat(string who,string message){var stack=new StackPanel();stack.Children.Add(new TextBlock{Text=who,FontSize=11,Foreground=Muted,Margin=new(0,0,0,4)});stack.Children.Add(Text(message));chatHistory.Children.Add(new Border{Child=stack,Padding=new(12),Background=Surface,CornerRadius=new(9),Margin=new(0,0,0,8)});while(chatHistory.Children.Count>30)chatHistory.Children.RemoveAt(0);}
    void OnReply(string input,string reply,double seconds){AddChat(Program.Config.PetName,reply);chatHint.Text=seconds>0?$"已回应 · {seconds:F2} 秒":"连接失败，请检查设置。";}
    void Export(){try{var d=new SaveFileDialog{Filter="JSON 配置|*.json",FileName="grok-settings.json"};if(d.ShowDialog(this)!=true)return;var safe=Program.Config.Clone();safe.X=safe.Y=double.NaN;File.WriteAllText(d.FileName,JsonSerializer.Serialize(safe,Program.JsonOptions));Toast("已导出");}catch(Exception e){Toast(e.Message,true);}}
    void Import(){try{var d=new OpenFileDialog{Filter="JSON 配置|*.json"};if(d.ShowDialog(this)!=true)return;if(new FileInfo(d.FileName).Length>1_000_000)throw new InvalidDataException("配置文件超过 1MB，请检查文件。");var imported=JsonSerializer.Deserialize<Settings>(File.ReadAllText(d.FileName),Program.JsonOptions)??throw new InvalidDataException("配置格式不正确。");imported.Normalize();foreach(var importedProfile in imported.Connections){string oldId=importedProfile.Id;importedProfile.Id=Guid.NewGuid().ToString("N");if(imported.ActiveConnectionId==oldId)imported.ActiveConnectionId=importedProfile.Id;}if(MessageBox.Show(this,"导入并替换当前配置？","导入设置",MessageBoxButton.YesNo,MessageBoxImage.Question)!=MessageBoxResult.Yes)return;File.WriteAllText(Path.Combine(Program.DataDir,"settings.before-import.json"),JsonSerializer.Serialize(Program.Config,Program.JsonOptions));imported.X=Program.Config.X;imported.Y=Program.Config.Y;pet.ApplySettings(imported);Close();pet.OpenControl("模型连接");}catch(Exception e){Toast(e.Message,true);}}
    void ExportDiagnostics(){try{var d=new SaveFileDialog{Filter="JSON 摘要|*.json",FileName="grok-diagnostics.json"};if(d.ShowDialog(this)!=true)return;File.WriteAllText(d.FileName,JsonSerializer.Serialize(new{version="0.2",framework=System.Runtime.InteropServices.RuntimeInformation.FrameworkDescription,provider=Program.Config.Active.Provider,transport=Program.Config.Active.NativeR1?"native-r1":"compatible-chat",model=Program.Config.Active.Model,requests=pet.Service.RequestCount,lastResponseSeconds=pet.LastReplySeconds,lastError=pet.LastError.Length>0?"connection-or-format-error":"",note="No keys, endpoint addresses, prompts or conversation text included."},Program.JsonOptions));Toast("已导出");}catch(Exception e){Toast(e.Message,true);}}
}
public class FacePreview:FrameworkElement {
    protected override void OnRender(DrawingContext dc){double size=Math.Min(ActualWidth,ActualHeight),scale=size/256;dc.PushTransform(new TranslateTransform((ActualWidth-size)/2,(ActualHeight-size)/2));dc.PushTransform(new ScaleTransform(scale,scale));var brush=new RadialGradientBrush(Colors.White,Color.FromRgb(218,225,239)){Center=new(.35,.25),GradientOrigin=new(.35,.25),RadiusX=.9,RadiusY=.9};dc.DrawEllipse(brush,null,new(128,128),109,109);dc.DrawGeometry(new SolidColorBrush(Color.FromRgb(24,26,31)),null,SphereEyes.Path(0,10,1,-1));dc.DrawGeometry(new SolidColorBrush(Color.FromRgb(24,26,31)),null,SphereEyes.Path(0,10,1,1));dc.Pop();dc.Pop();}
